                self.pos = @intCast(p);
                return token(.@"err", pre, start, p);
            },
            56 => {
                if (p < n and cls8[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '0'...'9', 'A'...'F', 'a'...'f' => { p += 1; continue :dfa 76; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"err", pre, start, p);
            },
            57 => {
                if (p < n and cls0[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '0'...'9' => { p += 1; continue :dfa 19; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"err", pre, start, p);
            },
            58 => {
                if (p < n) switch (src[p]) {
                    '=' => { p += 1; self.pos = @intCast(p); return token(.@"lshift_assign", pre, start, p); },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"lshift", pre, start, p);
            },
            64 => {
                if (p < n) switch (src[p]) {
                    '=' => { p += 1; self.pos = @intCast(p); return token(.@"rshift_assign", pre, start, p); },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"rshift", pre, start, p);
            },
            67 => {
                if (p < n) switch (src[p]) {
                    '\n' => { p += 1; self.pos = @intCast(p); return token(.@"skip", pre, start, p); },
                    else => {},
                };
                break :dfa;
            },
            71 => {
                if (p < n) switch (src[p]) {
                    '+', '-' => { p += 1; continue :dfa 80; },
                    '0'...'9' => { p += 1; continue :dfa 81; },
                    else => {},
                };
                break :dfa;
            },
            72 => {
                if (p < n) switch (src[p]) {
                    '0'...'9' => { p += 1; continue :dfa 82; },
                    else => {},
                };
                break :dfa;
            },
            73 => {
                while (p < n and src[p] -% '0' <= 9) p += 1;
                if (p < n and cls9[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '_' => { p += 1; continue :dfa 83; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"real", pre, start, p);
            },
            74 => {
                while (p < n and src[p] -% '0' <= 1) p += 1;
                if (p < n and cls10[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '_' => { p += 1; continue :dfa 54; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"integer", pre, start, p);
            },
            75 => {
                while (p < n and src[p] -% '0' <= 7) p += 1;
                if (p < n and cls11[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '_' => { p += 1; continue :dfa 55; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"integer", pre, start, p);
            },
            76 => {
                while (p < n and cls12[src[p]]) p += 1;
                if (p < n and cls13[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '_' => { p += 1; continue :dfa 56; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"integer", pre, start, p);
            },
            80 => {
                if (p < n) switch (src[p]) {
                    '0'...'9' => { p += 1; continue :dfa 81; },
                    else => {},
                };
                break :dfa;
            },
            81 => {
                while (p < n and src[p] -% '0' <= 9) p += 1;
                acc = 10;
                accEnd = p;
                if (p < n) switch (src[p]) {
                    '_' => { p += 1; continue :dfa 80; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"real", pre, start, p);
            },
            82 => {
                while (p < n and src[p] -% '0' <= 9) p += 1;
                acc = 11;
                accEnd = p;
                if (p < n) switch (src[p]) {
                    '_' => { p += 1; continue :dfa 72; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"real", pre, start, p);
            },
            83 => {
                if (p < n and cls0[src[p]]) {
                    p += 1;
                    continue :dfa 52;
                }
                if (p < n) switch (src[p]) {
                    '0'...'9' => { p += 1; continue :dfa 73; },
                    else => {},
                };
                self.pos = @intCast(p);
                return token(.@"err", pre, start, p);
            },
            else => unreachable,
        }
        switch (acc) {
            61 => {
                p = accEnd;
                self.pos = @intCast(p);
                return token(.@"err", pre, start, p);
            },
            12 => {
                p = accEnd;
                self.pos = @intCast(p);
                return token(.@"integer", pre, start, p);
            },
            6 => {
                p = accEnd;
                self.pos = @intCast(p);
                return token(.@"string_sq", pre, start, p);
            },
            10 => {
                p = accEnd;
                self.pos = @intCast(p);
                return token(.@"real", pre, start, p);
            },
            13 => {
                p = accEnd;
                self.pos = @intCast(p);
                return token(.@"err", pre, start, p);
            },
            11 => {
                p = accEnd;
                self.pos = @intCast(p);
                return token(.@"real", pre, start, p);
            },
            else => {},
        }
        self.pos = @intCast(start + 1);
        return .{ .cat = .@"err", .pre = pre, .pos = @intCast(start), .len = 1 };
    }
};

pub const Lexer = if (@hasDecl(lang, "Lexer")) lang.Lexer else BaseLexer;

